<?php require_once __DIR__.'/../includes/bootstrap.php';require_perm('documents.manage');check_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){try{$id=(int)$_POST['id'];$st=$_POST['status'];$remarks=trim($_POST['remarks']);db()->prepare('UPDATE documents SET verification_status=?,verified_by=?,remarks=? WHERE id=?')->execute([$st,actor_id(),$remarks,$id]);AuditService::log('DOCUMENT_VERIFY','documents',$id,$st);$_SESSION['flash']=['success','Document updated'];}catch(Throwable $e){$_SESSION['flash']=['danger',$e->getMessage()];}redirect('documents.php');}$rows=db()->query('SELECT d.*,u.name owner_name FROM documents d JOIN users u ON u.id=d.owner_user_id ORDER BY d.id DESC')->fetchAll();page_top('Digital Document Verification');flash();?><div class='card p-3 table-responsive'><table class='table'><tr><th>Owner</th><th>Title</th><th>Category</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['owner_name'])?></td><td><?=e($r['title'])?></td><td><?=e($r['category'])?></td><td><?=e($r['verification_status'])?></td><td><form method='post' class='d-flex gap-2'><input type='hidden' name='csrf' value='<?=e(csrf_token())?>'><input type='hidden' name='id' value='<?=e($r['id'])?>'><select name='status' class='form-select form-select-sm'><option <?=($r['verification_status']==='Approved'?'selected':'')?>>Approved</option><option <?=($r['verification_status']==='Rejected'?'selected':'')?>>Rejected</option><option <?=($r['verification_status']==='Correction Required'?'selected':'')?>>Correction Required</option></select><input name='remarks' class='form-control form-control-sm' value='<?=e($r['remarks']??'')?>'><button class='btn btn-sm btn-primary'>Save</button><a class='btn btn-sm btn-outline-secondary' href='../files/download.php?id=<?=e($r['id'])?>'>Download</a></form></td></tr><?php endforeach;?></table></div><?php page_bottom();
